TLM.f("Sancti/01-19",{"officium":"Ss. Marii, Marthæ, Audifacis et Abachum Martyrum","rule":["vide C3;","Gloria"],"fallback":"Commune/C3","sections":{"Introitus":[{"k":"ref","la":"Ps 67:4"},{"k":"text","la":"Justi epuléntur et exsúltent in conspéctu Dei et delecténtur in lætítia."},{"k":"ref","la":"Ps 67:2"},{"k":"text","la":"Exsúrgat Deus, et dissipéntur inimíci ejus: et fúgiant qui odérunt eum, a fácie ejus."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Justi epuléntur et exsúltent in conspéctu Dei et delecténtur in lætítia."}],"Oratio":[{"k":"text","la":"Exáudi, Dómine, pópulum tuum cum Sanctórum tuórum patrocínio supplicántem: ut et temporális vitæ nos tríbuas pace gaudére; et ætérnæ reperíre subsídium."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Hebrǽos"},{"k":"ref","la":"Hebr 10:32-38"},{"k":"text","la":"Fratres: Rememorámini prístinos dies, in quibus illumináti magnum certámen sustinuístis passiónum: et in áltero quidem oppróbriis et tribulatiónibus spectáculum facti: in áltero autem sócii táliter conversántium effécti. Nam et vinctis compássi estis, et rapínam bonórum vestrórum cum gáudio suscepístis, cognoscéntes vos habere meliórem et manéntem substántiam. Nolíte itaque amíttere confidéntiam vestram, quæ magnam habet remuneratiónem. Patiéntia enim vobis necéssaria est: ut, voluntátem Dei faciéntes, reportétis promissiónem. Adhuc enim módicum aliquántulum, qui ventúrus est, véniet, et non tardábit. Justus autem meus ex fide vivit."}],"Graduale":[{"k":"ref","la":"Sap 3:1; 3:2; 3:3"},{"k":"text","la":"Justórum ánimæ in manu Dei sunt: et non tanget illos torméntum malítiæ."},{"k":"text","la":"Visi sunt óculis insipiéntium mori: illi autem sunt in pace.","mark":"V"},{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Ps 67:36"},{"k":"text","la":"Mirábilis Deus noster in Sanctis suis. Allelúja."}],"Tractus":[{"k":"ref","la":"Ps 125:5-6"},{"k":"text","la":"Qui séminant in lácrimis, in gáudio metent."},{"k":"text","la":"Eúntes ibant et flébant, mitténtes semina sua.","mark":"V"},{"k":"text","la":"Veniéntes autem vénient cum exsultatióne, portántes manípulos suos.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Matthǽum"},{"k":"ref","la":"Matt 24:3-13"},{"k":"text","la":"In illo témpore: Sedénte Jesu super montem Olivéti, accessérunt ad eum discípuli secréto, dicéntes: Dic nobis, quando hæc erunt? et quod signum advéntus tui et consummatiónis sǽculi? Et respóndens Jesus, dixit eis: Vidéte, ne quis vos sedúcat. Multi enim vénient in nómine meo, dicéntes: Ego sum Christus: et multos sedúcent. Auditúri enim estis prælia et opiniónes prœliórum. Vidéte, ne turbémini. Opórtet enim hæc fíeri, sed nondum est finis. Consúrget enim gens in gentem, et regnum in regnum, et erunt pestiléntiæ et fames et terræmótus per loca. Hæc autem ómnia inítia sunt dolórum. Tunc tradent vos in tribulatiónem et occídent vos: et éritis odio ómnibus géntibus propter nomen meum. Et tunc scandalizabúntur multi, et ínvicem tradent, et odio habébunt ínvicem. Et multi pseudoprophétæ surgent, et sedúcent multos. Et quóniam abundávit iníquitas, refrigéscet cáritas multórum. Qui autem perseveráverit usque in finem, hic salvus erit."}],"Offertorium":[{"k":"ref","la":"Ps 128:7"},{"k":"text","la":"Anima nostra, sicut passer, erépta est de láqueo venántium: láqueus contrítus est, et nos liberáti sumus."}],"Secreta":[{"k":"text","la":"Preces, Dómine, tuórum réspice oblationésque fidélium: ut et tibi gratæ sint pro tuórum festivitáte Sanctórum, et nobis cónferant tuæ propitiatiónis auxílium."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Luc 12:4"},{"k":"text","la":"Dico autem vobis amícis meis: Ne terreámini ab his, qui vos persequúntur."}],"Postcommunio":[{"k":"text","la":"Sanctórum tuórum, Dómine, intercessióne placátus: præsta, quǽsumus; ut, quæ temporáli celebrámus actióne, perpétua salvatióne capiámus."},{"k":"macro","name":"Per Dominum"}]},"hr":{"dd0b5d4c8143cd30":{"t":"<i>Pomolimo se</i>.\nUsliši, Gospodine, svoj narod koji ti vapije pod zaštitom tvojih svetih, i daj da se radujemo miru u zemaljskom životu i nađemo pomoć za vječnost.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Usliši, Gospodine, puk svoj, koji sjedinjuje molitve svoje s molitvama svetih Tvojih i daj, da se radujemo miru vremenitog života i zadobiiemo pomoć za vječni, po G. n.","knRef":"Kniewald 1942, str. 480–481 (snimka 241) (OCR)"},"db8921a4d107e2d5":{"t":"Pogledaj, Gospodine, na molitve i prinose svojih vjernika, da budu i tebi mili zbog svetkovine tvojih svetih i nama donesu tvoju milostivu pomoć.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Pogledaj, Gospodine, molitve i žrtve Tvojih vjernika, da Ti budu drage, jer ih prinosimo o svetkovini Tvojih svetih, a nama da pruže pomoć Tvojeg pomirenja, po G. n.","knRef":"Kniewald 1942, str. 522–523 (snimka 262) (OCR)"},"0557456d36d8e952":{"t":"<i>Pomolimo se</i>.\nUmilostivljen, Gospodine, posredovanjem tvojih svetih, daj, molimo, da postignemo u trajnom spasenju što slavimo vremenitim činom.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."}}});
